def add(n,spelling,ipa,definition,page,group,senses,examples,mnemonic='',related=(),notes=()):
    ss=[dict(id=f's{n:04}-{i+1:02}',pos=p,gloss=g,origin='editor_mapping',ready=False) for i,(p,g) in enumerate(senses)]
    ee=[]
    for j,(si,en,zh,target,label,p) in enumerate(examples):
        start=en.index(target)
        ee.append(dict(id=f'e{n:04}-{j+1:02}',sense_id=ss[si]['id'],english=en,translation=zh,target=target,target_start=start,target_end=start+len(target),book_label=label,pdf_page=p,printed_page=f'{p-8:03}',review_status='visual_checked',note='真题标签仅据原书，年份题号未核实。' if label=='真题' else ''))
        ss[si]['ready']=True
    pages=sorted(set([page]+[e['pdf_page'] for e in ee]))
    words.append(dict(id=f'w{n:04}',spelling=spelling,phonetic=ipa,source_definition=definition,mnemonic=mnemonic,group_name=group,pdf_pages=pages,printed_pages=[f'{p-8:03}' for p in pages],review_status='visual_checked',senses=ss,examples=ee,related=[dict(id=f'r{n:04}-{i+1:02}',spelling=s,definition=d,relation='derived',pdf_page=p,note='仅作关联资料，不自动计入主词掌握进度。') for i,(s,d,p) in enumerate(related)],notes=list(notes)))

